/*
 * prog41_series_sum – reconstructed from the obfuscated binary.
 *
 * The program expects exactly two integer arguments:
 *   1) mode  – either 2 or 3
 *   2) limit – a non‑negative integer not larger than 100 000
 *
 * Behaviour
 * ----------
 *   * If fewer than two arguments are supplied → prints "NO_INPUT".
 *   * If either argument is not a valid decimal integer → prints "BAD_INPUT".
 *   * If the second argument is negative or larger than 100 000 → prints "OUT_OF_RANGE".
 *   * If the first argument is not 2 or 3 → prints "BAD_MODE".
 *
 *   For a valid input the program computes a series sum and prints it
 *   with six digits after the decimal point:
 *
 *        mode == 2 :  Σ_{i=1}^{limit} 1.0 / i                (harmonic series)
 *        mode == 3 :  1.0 + Σ_{i=1}^{limit} 1.0 / i
 *
 *   When limit == 0 the sum is 0.0 for mode 2 and 1.0 for mode 3.
 *
 *   The output format is exactly the same as the original binary:
 *        printf("%.6f\n", sum);
 *
 *   All messages are printed with a trailing newline, matching the
 *   original strings found in the binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
       1) Argument count check – the original program prints "NO_INPUT"
       when argc < 3 (program name + two arguments).
       ----------------------------------------------------------------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
       2) Parse the first argument (mode).  Use strtol and verify that the
       whole string was consumed and that no overflow/underflow occurred.
       ----------------------------------------------------------------- */
    char *endptr1 = NULL;
    errno = 0;
    long mode = strtol(argv[1], &endptr1, 10);
    if (errno != 0 || *endptr1 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
       3) Parse the second argument (limit).  Same validation as above.
       ----------------------------------------------------------------- */
    char *endptr2 = NULL;
    errno = 0;
    long limit = strtol(argv[2], &endptr2, 10);
    if (errno != 0 || *endptr2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
       4) Range checks for the second argument.
       ----------------------------------------------------------------- */
    if (limit < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (limit > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* -----------------------------------------------------------------
       5) Mode validation.
       ----------------------------------------------------------------- */
    if (mode != 2 && mode != 3) {
        puts("BAD_MODE");
        return 0;
    }

    /* -----------------------------------------------------------------
       6) Compute the required series.
       ----------------------------------------------------------------- */
    const double C = 1.0;          /* the constant stored at DAT_00102008 */
    double sum = 0.0;

    if (mode == 3) {
        sum = C;                    /* the leading “1.0” term for mode 3 */
    }

    for (long i = 1; i <= limit; ++i) {
        sum += C / (double)i;
    }

    /* -----------------------------------------------------------------
       7) Print the result with exactly six digits after the decimal point.
       ----------------------------------------------------------------- */
    printf("%.6f\n", sum);
    return 0;
}
